const std = @import("std");
pub const Node = struct { label: []const u8, children: []const *const Node = &.{} };
pub const Tree = struct {
    arena: std.heap.ArenaAllocator,
    root: *const Node,
    pub fn deinit(s: *Tree) void {
        s.arena.deinit();
    }
};
fn find(n: *const Node, label: []const u8) ?*const Node {
    if (std.mem.eql(u8, n.label, label)) return n;
    for (n.children) |c| {
        if (find(c, label)) |r| return r;
    }
    return null;
}
fn parent(root: *const Node, node: *const Node) ?*const Node {
    for (root.children) |c| {
        if (c == node) return root;
        if (parent(c, node)) |p| return p;
    }
    return null;
}
fn orient(a: std.mem.Allocator, root: *const Node, node: *const Node, previous: ?*const Node) std.mem.Allocator.Error!*const Node {
    var children = std.array_list.Managed(*const Node).init(a);
    defer children.deinit();
    for (node.children) |c| {
        if (c != previous) try children.append(try orient(a, root, c, node));
    }
    if (parent(root, node)) |p| {
        if (p != previous) try children.append(try orient(a, root, p, node));
    }
    const n = try a.create(Node);
    n.* = .{ .label = node.label, .children = try children.toOwnedSlice() };
    return n;
}
pub fn fromPov(a: std.mem.Allocator, root: *const Node, label: []const u8) !Tree {
    const n = find(root, label) orelse return error.TreeCouldNotBeReoriented;
    var arena = std.heap.ArenaAllocator.init(a);
    errdefer arena.deinit();
    const result = try orient(arena.allocator(), root, n, null);
    return .{ .arena = arena, .root = result };
}
fn path(n: *const Node, label: []const u8, out: *std.array_list.Managed([]const u8)) std.mem.Allocator.Error!bool {
    try out.append(n.label);
    if (std.mem.eql(u8, n.label, label)) return true;
    for (n.children) |c| {
        if (try path(c, label, out)) return true;
    }
    _ = out.pop();
    return false;
}
pub fn pathTo(a: std.mem.Allocator, root: *const Node, from: []const u8, to: []const u8) ![][]const u8 {
    var tree = try fromPov(a, root, from);
    defer tree.deinit();
    var out = std.array_list.Managed([]const u8).init(a);
    errdefer out.deinit();
    if (!try path(tree.root, to, &out)) return error.NoPathFound;
    return out.toOwnedSlice();
}

