// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("pov.zig");
test "reroot retains descendants and siblings and paths" {
    const leaf = m.Node{ .label = "x" };
    const sibling = m.Node{ .label = "sibling" };
    const parent = m.Node{ .label = "parent", .children = &.{ &leaf, &sibling } };
    const cousin = m.Node{ .label = "cousin" };
    const uncle = m.Node{ .label = "uncle", .children = &.{&cousin} };
    const root = m.Node{ .label = "root", .children = &.{ &parent, &uncle } };
    var tree = try m.fromPov(t.allocator, &root, "x");
    defer tree.deinit();
    try t.expectEqualStrings("x", tree.root.label);
    const p = tree.root.children[0];
    try t.expectEqualStrings("parent", p.label);
    try t.expectEqual(@as(usize, 2), p.children.len);
    try t.expectEqualStrings("sibling", p.children[0].label);
    try t.expectEqualStrings("root", p.children[1].label);
    const labels = try m.pathTo(t.allocator, &root, "x", "cousin");
    defer t.allocator.free(labels);
    const expected = [_][]const u8{ "x", "parent", "root", "uncle", "cousin" };
    try t.expectEqual(expected.len, labels.len);
    for (labels, expected) |x, y| try t.expectEqualStrings(y, x);
    try t.expectError(error.NoPathFound, m.pathTo(t.allocator, &root, "x", "missing"));
    try t.expectError(error.TreeCouldNotBeReoriented, m.fromPov(t.allocator, &root, "missing"));
    try t.expectEqualStrings("root", root.label);
}
fn sameTree(a: *const m.Node, b: *const m.Node) anyerror!void {
    try t.expectEqualStrings(b.label, a.label);
    try t.expectEqual(b.children.len, a.children.len);
    for (b.children) |expected| {
        var found = false;
        for (a.children) |actual| {
            if (std.mem.eql(u8, actual.label, expected.label)) {
                try sameTree(actual, expected);
                found = true;
                break;
            }
        }
        try t.expect(found);
    }
}
